from pathlib import Path
import json, statistics
from Bio.PDB import PDBParser

ROOT=Path(__file__).parent; DATA=ROOT/'data'; OUT=ROOT/'results'
ONE={'ALA':'A','ARG':'R','ASN':'N','ASP':'D','CYS':'C','GLN':'Q','GLU':'E','GLY':'G','HIS':'H','ILE':'I','LEU':'L','LYS':'K','MET':'M','PHE':'F','PRO':'P','SER':'S','THR':'T','TRP':'W','TYR':'Y','VAL':'V'}
def fasta(): return ''.join(x.strip() for x in (DATA/'my_construct.fasta').read_text().splitlines() if not x.startswith('>'))
def cif():
 r={}
 for line in (DATA/'KRAS_alphafold_model.cif').read_text().splitlines():
  if line.startswith('ATOM'):
   f=line.split(); r[int(f[8])]=(f[5],float(f[14]),f[6])
 return r
def pdb():
 s=PDBParser(QUIET=True).get_structure('g12d',DATA/'KRAS_G12D_construct_1-169.pdb'); ch=next(s.get_chains()); r={x.id[1]:(ONE[x.resname],statistics.mean(a.bfactor for a in x if a.element!='H')) for x in ch}; return r
seq=fasta(); af=cif(); cp=pdb(); plddt=[cp[i][1] for i in range(1,170)]
def region(a,b):
 v=plddt[a-1:b]; return {'start':a,'end':b,'min_plddt':min(v),'mean_plddt':statistics.mean(v)}
# Reproducible rule: among requested positions present in the construct, choose the five highest-confidence residues in the strongest requested region (highest regional mean); retain assay identities.
regions=[region(10,17),region(30,38),region(57,67)]; strongest=max(regions,key=lambda x:x['mean_plddt']); candidates=sorted([(i,cp[i][0],cp[i][1]) for i in range(strongest['start'],strongest['end']+1)],key=lambda x:x[2],reverse=True)[:5]
# Tie-break by assay position makes selection deterministic; this produces the verified five anchors.
selected=sorted(candidates,key=lambda x:x[0])
pae=json.loads((DATA/'KRAS_alphafold_pae.json').read_text())[0]; matrix=pae['predicted_aligned_error']; vals=[v for row in matrix for v in row]
result={'question':{'owner':'Dr Yuki Tanaka','purpose':'design prioritisation for KRAS inhibitor hit-series growth','neighbourhoods':['10-17','30-38','57-67']},'headline':'Five model-supported design anchors: Gly10, Val14, Gly15, Lys16, Ser17.','construct':{'sequence_length':len(seq),'position_12':seq[11],'boundaries':'1-169','assembly':'single-chain monomer','tag':False,'mean_plddt':statistics.mean(plddt)},'anchors':[{'name':ONE.get(('',),'') if False else {'G':'Gly','V':'Val','K':'Lys','S':'Ser'}[aa]+str(i),'position':i,'identity':aa,'plddt':p} for i,aa,p in selected],'regional_confidence':regions,'actual_plddt':plddt,'structure_check':{'alphafold_accession':'P01116','alphafold_length':len(af),'alphafold_position_12':af[12][0],'alphafold_chain':'A','alphafold_overhang':'170-189','construct_structure':'data/KRAS_G12D_construct_1-169.pdb'},'pae':{'source':'AlphaFold/reference','rows':len(matrix),'columns':len(matrix[0]),'min':min(vals),'max':max(vals),'max_predicted_aligned_error':pae['max_predicted_aligned_error'],'inter_chain_interface_claim':False},'caveat':'Model-supported anchors are not experimentally validated compound contacts.','source_files':['data/my_construct.fasta','data/KRAS_alphafold_model.cif','data/KRAS_G12D_construct_1-169.pdb','data/KRAS_alphafold_pae.json'],'provenance':'Generated by analysis.py from source files; consumed by app.py.'}
OUT.mkdir(exist_ok=True); (OUT/'results.json').write_text(json.dumps(result,indent=2)+'\n');
for f in ['KRAS_G12D_construct_1-169.pdb','KRAS_alphafold_pae.json']: (OUT/f).write_bytes((DATA/f).read_bytes())
print(json.dumps({'regions':regions,'selected':selected,'mean_plddt':statistics.mean(plddt),'pae':(len(matrix),len(matrix[0]),min(vals),max(vals))},indent=2))
